import pandas as pd
def parse(s, t0, step_ms):
    rows = [list(map(int, x.split(','))) for x in s.split(';')]
    df = pd.DataFrame(rows, columns=['o', 'h', 'l', 'c'])
    df['t'] = pd.to_datetime([t0 + i * step_ms for i in range(len(df))], unit='ms', utc=True)
    return df

